import importlib.util
import types
import sys

# Mock modules
for mod_name in ['astropy', 'astropy.utils', 'astropy.utils.decorators', 
                'astropy.utils.exceptions', 'astropy.utils.decorators',
                'astropy.utils.multidict', 'astropy.utils.state']:
    if mod_name not in sys.modules:
        parts = mod_name.split('.')
        for i in range(len(parts)):
            p = '.'.join(parts[:i+1])
            if p not in sys.modules:
                sys.modules[p] = types.ModuleType(p)

